-- CommerceFlow core schema at V74. All commerce timestamps use UTC.

CREATE EXTENSION IF NOT EXISTS unaccent WITH SCHEMA public;

CREATE COLLATION commerce_ai_ci (provider = icu, locale = 'und-u-ks-level1', deterministic = false);

CREATE TABLE "app_users" (
    "id" bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "email" varchar(190) COLLATE commerce_ai_ci NOT NULL,
    "password_hash" varchar(100) COLLATE commerce_ai_ci NOT NULL,
    "first_name" varchar(80) COLLATE commerce_ai_ci NOT NULL,
    "last_name" varchar(80) COLLATE commerce_ai_ci NOT NULL,
    "phone" varchar(40) COLLATE commerce_ai_ci NOT NULL,
    "role" varchar(30) COLLATE commerce_ai_ci NOT NULL,
    "enabled" boolean NOT NULL,
    PRIMARY KEY ("id")
);

ALTER TABLE "app_users" ADD CONSTRAINT "uk_app_users_email" UNIQUE ("email");

CREATE TABLE "cart_items" (
    "id" bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "cart_id" bigint NOT NULL,
    "product_id" bigint NOT NULL,
    "merchant_id" bigint,
    "product_name" varchar(160) COLLATE commerce_ai_ci NOT NULL,
    "thumbnail_url" varchar(500) COLLATE commerce_ai_ci NOT NULL,
    "unit_price" decimal(12,2) NOT NULL,
    "quantity" integer NOT NULL,
    "created_at" timestamp(6) with time zone DEFAULT CURRENT_TIMESTAMP(6) NOT NULL,
    "updated_at" timestamp(6) with time zone DEFAULT CURRENT_TIMESTAMP(6) NOT NULL,
    PRIMARY KEY ("id"),
    CONSTRAINT "ck_cart_items_quantity" CHECK ("quantity" between 1 and 99)
);

CREATE INDEX "fk_cart_items_product" ON "cart_items" ("product_id");

ALTER TABLE "cart_items" ADD CONSTRAINT "uk_cart_items_product" UNIQUE ("cart_id", "product_id");

CREATE TABLE "cart_repurchase_requests" (
    "customer_id" bigint NOT NULL,
    "request_id" char(36) COLLATE commerce_ai_ci NOT NULL,
    "order_id" bigint NOT NULL,
    "result_json" text COLLATE commerce_ai_ci NOT NULL,
    "created_at" timestamp(6) with time zone DEFAULT CURRENT_TIMESTAMP(6) NOT NULL,
    PRIMARY KEY ("customer_id", "request_id")
);

COMMENT ON TABLE "cart_repurchase_requests" IS 'Transactional receipts for retrying cart repurchase';

COMMENT ON COLUMN "cart_repurchase_requests"."customer_id" IS 'Owner of the cart and source order';

COMMENT ON COLUMN "cart_repurchase_requests"."request_id" IS 'Client UUID for one repurchase attempt';

COMMENT ON COLUMN "cart_repurchase_requests"."order_id" IS 'Authoritative source order identifier';

COMMENT ON COLUMN "cart_repurchase_requests"."result_json" IS 'Original outcome replayed for duplicate requests';

CREATE TABLE "carts" (
    "id" bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "user_id" bigint NOT NULL,
    "created_at" timestamp(6) with time zone DEFAULT CURRENT_TIMESTAMP(6) NOT NULL,
    "updated_at" timestamp(6) with time zone DEFAULT CURRENT_TIMESTAMP(6) NOT NULL,
    "selected_address_id" bigint,
    PRIMARY KEY ("id")
);

CREATE INDEX "fk_carts_selected_address" ON "carts" ("selected_address_id");

ALTER TABLE "carts" ADD CONSTRAINT "uk_carts_user" UNIQUE ("user_id");

CREATE TABLE "catalog_event_outbox" (
    "id" bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "event_id" varchar(100) COLLATE commerce_ai_ci NOT NULL,
    "event_type" varchar(50) COLLATE commerce_ai_ci NOT NULL,
    "aggregate_id" bigint NOT NULL,
    "schema_version" integer NOT NULL,
    "business_version" bigint NOT NULL,
    "occurred_at" timestamp(6) with time zone NOT NULL,
    "correlation_id" varchar(100) COLLATE commerce_ai_ci NOT NULL,
    "causation_id" varchar(100) COLLATE commerce_ai_ci NOT NULL,
    "payload" jsonb NOT NULL,
    "status" varchar(20) COLLATE commerce_ai_ci DEFAULT 'NEW' NOT NULL,
    "attempts" integer DEFAULT '0' NOT NULL,
    "next_attempt_at" timestamp(6) with time zone DEFAULT CURRENT_TIMESTAMP(6) NOT NULL,
    "last_error" varchar(500) COLLATE commerce_ai_ci,
    "created_at" timestamp(6) with time zone DEFAULT CURRENT_TIMESTAMP(6) NOT NULL,
    "published_at" timestamp(6) with time zone,
    PRIMARY KEY ("id"),
    CONSTRAINT "chk_catalog_event_status" CHECK ("status" in ('NEW','RETRY','PUBLISHED','DEAD'))
);

CREATE INDEX "ix_catalog_event_aggregate" ON "catalog_event_outbox" ("aggregate_id", "business_version");

CREATE INDEX "ix_catalog_event_dispatch" ON "catalog_event_outbox" ("status", "next_attempt_at");

ALTER TABLE "catalog_event_outbox" ADD CONSTRAINT "uk_catalog_event_id" UNIQUE ("event_id");

CREATE TABLE "checkout_intents" (
    "quote_id" char(64) COLLATE commerce_ai_ci NOT NULL,
    "customer_id" bigint NOT NULL,
    "scope_hash" char(64) COLLATE commerce_ai_ci NOT NULL,
    "order_number" varchar(40) COLLATE commerce_ai_ci NOT NULL,
    "order_id" bigint,
    "coupon_id" char(36) COLLATE commerce_ai_ci,
    "status" varchar(12) COLLATE commerce_ai_ci NOT NULL,
    "payload" jsonb NOT NULL,
    "next_attempt_at" timestamp(6) with time zone DEFAULT CURRENT_TIMESTAMP(6) NOT NULL,
    "created_at" timestamp(6) with time zone DEFAULT CURRENT_TIMESTAMP(6) NOT NULL,
    "updated_at" timestamp(6) with time zone DEFAULT CURRENT_TIMESTAMP(6) NOT NULL,
    "pending_customer_id" bigint GENERATED ALWAYS AS ((case when ("status" = 'PREPARED') then "customer_id" end)) STORED,
    PRIMARY KEY ("quote_id"),
    CONSTRAINT "checkout_intents_chk_1" CHECK ("status" in ('PREPARED','BOUND','COMPLETE','USED','RETURNED'))
);

CREATE INDEX "fk_checkout_intent_coupon" ON "checkout_intents" ("coupon_id");

CREATE INDEX "idx_checkout_intent_recovery" ON "checkout_intents" ("status", "next_attempt_at");

ALTER TABLE "checkout_intents" ADD CONSTRAINT "uk_checkout_intent_order" UNIQUE ("order_id");

ALTER TABLE "checkout_intents" ADD CONSTRAINT "uk_checkout_intent_pending_customer" UNIQUE ("pending_customer_id");

COMMENT ON COLUMN "checkout_intents"."quote_id" IS '已确认报价的 SHA-256，复用为下单幂等标识';

COMMENT ON COLUMN "checkout_intents"."customer_id" IS '授权下单的顾客';

COMMENT ON COLUMN "checkout_intents"."scope_hash" IS '确认请求范围摘要';

COMMENT ON COLUMN "checkout_intents"."order_number" IS '恢复时复用的订单号';

COMMENT ON COLUMN "checkout_intents"."order_id" IS '订单服务生成的订单 ID';

COMMENT ON COLUMN "checkout_intents"."coupon_id" IS '可选顾客券实例';

COMMENT ON COLUMN "checkout_intents"."status" IS 'PREPARED、BOUND、COMPLETE、USED 或 RETURNED';

COMMENT ON COLUMN "checkout_intents"."payload" IS '确认时冻结的持久化下单数据';

CREATE TABLE "checkout_receipts" (
    "customer_id" bigint NOT NULL,
    "quote_id" char(64) COLLATE commerce_ai_ci NOT NULL,
    "scope_hash" char(64) COLLATE commerce_ai_ci NOT NULL,
    "order_id" bigint NOT NULL,
    PRIMARY KEY ("customer_id", "quote_id")
);

ALTER TABLE "checkout_receipts" ADD CONSTRAINT "uk_checkout_receipts_order" UNIQUE ("order_id");

COMMENT ON COLUMN "checkout_receipts"."customer_id" IS '确认结算的顾客';

COMMENT ON COLUMN "checkout_receipts"."quote_id" IS '已确认报价的 SHA-256';

COMMENT ON COLUMN "checkout_receipts"."scope_hash" IS '下单请求所选地址和条目的摘要';

COMMENT ON COLUMN "checkout_receipts"."order_id" IS '订单服务生成的订单 ID';

CREATE TABLE "coupon_campaigns" (
    "id" char(36) COLLATE commerce_ai_ci NOT NULL,
    "merchant_id" bigint NOT NULL,
    "title" varchar(100) COLLATE commerce_ai_ci NOT NULL,
    "minimum_amount" decimal(12,2) NOT NULL,
    "discount_amount" decimal(12,2) NOT NULL,
    "supply" integer NOT NULL,
    "issued" integer DEFAULT '0' NOT NULL,
    "starts_at" timestamp(6) with time zone NOT NULL,
    "expires_at" timestamp(6) with time zone NOT NULL,
    "enabled" boolean DEFAULT true NOT NULL,
    PRIMARY KEY ("id"),
    CONSTRAINT "coupon_campaigns_chk_1" CHECK (("discount_amount" > 0) and ("minimum_amount" > "discount_amount")),
    CONSTRAINT "coupon_campaigns_chk_2" CHECK (("supply" > 0) and ("issued" between 0 and "supply")),
    CONSTRAINT "coupon_campaigns_chk_3" CHECK ("starts_at" < "expires_at")
);

CREATE INDEX "idx_coupon_campaign_merchant" ON "coupon_campaigns" ("merchant_id", "starts_at");

COMMENT ON COLUMN "coupon_campaigns"."id" IS '活动版本标识，计价规则发布后冻结';

COMMENT ON COLUMN "coupon_campaigns"."merchant_id" IS '活动归属商家';

COMMENT ON COLUMN "coupon_campaigns"."title" IS '顾客可见活动名称';

COMMENT ON COLUMN "coupon_campaigns"."minimum_amount" IS '适用商品金额门槛，人民币元';

COMMENT ON COLUMN "coupon_campaigns"."discount_amount" IS '满减金额，人民币元';

COMMENT ON COLUMN "coupon_campaigns"."supply" IS '活动原始发放量';

COMMENT ON COLUMN "coupon_campaigns"."issued" IS '已领取总数，取消返还不会重新发放';

COMMENT ON COLUMN "coupon_campaigns"."starts_at" IS '开始领取和用券的时刻';

COMMENT ON COLUMN "coupon_campaigns"."expires_at" IS '领取和用券截止时刻';

COMMENT ON COLUMN "coupon_campaigns"."enabled" IS '商家停止活动后禁止新领和新用';

CREATE TABLE "customer_coupons" (
    "id" char(36) COLLATE commerce_ai_ci NOT NULL,
    "campaign_id" char(36) COLLATE commerce_ai_ci NOT NULL,
    "customer_id" bigint NOT NULL,
    "status" varchar(12) COLLATE commerce_ai_ci NOT NULL,
    "bound_quote" char(64) COLLATE commerce_ai_ci,
    "claimed_at" timestamp(6) with time zone DEFAULT CURRENT_TIMESTAMP(6) NOT NULL,
    PRIMARY KEY ("id"),
    CONSTRAINT "customer_coupons_chk_1" CHECK ("status" in ('AVAILABLE','HELD','USED','EXPIRED'))
);

CREATE INDEX "fk_customer_coupon_campaign" ON "customer_coupons" ("campaign_id");

ALTER TABLE "customer_coupons" ADD CONSTRAINT "uk_customer_coupon_campaign" UNIQUE ("customer_id", "campaign_id");

COMMENT ON COLUMN "customer_coupons"."id" IS '单张券的稳定标识';

COMMENT ON COLUMN "customer_coupons"."campaign_id" IS '原活动版本';

COMMENT ON COLUMN "customer_coupons"."customer_id" IS '领取人';

COMMENT ON COLUMN "customer_coupons"."status" IS 'AVAILABLE、HELD、USED 或 EXPIRED';

COMMENT ON COLUMN "customer_coupons"."bound_quote" IS '当前绑定或核销的确认报价';

CREATE TABLE "customer_notifications" (
    "id" bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "event_id" varchar(100) COLLATE commerce_ai_ci NOT NULL,
    "customer_id" bigint NOT NULL,
    "order_id" bigint,
    "notification_type" varchar(50) COLLATE commerce_ai_ci NOT NULL,
    "title" varchar(160) COLLATE commerce_ai_ci NOT NULL,
    "message" varchar(500) COLLATE commerce_ai_ci NOT NULL,
    "status" varchar(20) COLLATE commerce_ai_ci DEFAULT 'UNREAD' NOT NULL,
    "read_at" timestamp(6) with time zone,
    "created_at" timestamp(6) with time zone DEFAULT CURRENT_TIMESTAMP(6) NOT NULL,
    PRIMARY KEY ("id")
);

CREATE INDEX "fk_customer_notification_customer" ON "customer_notifications" ("customer_id");

CREATE INDEX "fk_customer_notification_order" ON "customer_notifications" ("order_id");

ALTER TABLE "customer_notifications" ADD CONSTRAINT "uk_customer_notification_event" UNIQUE ("event_id");

CREATE TABLE "fulfillment_write_admission" (
    "singleton_id" smallint NOT NULL,
    "frozen" boolean NOT NULL,
    "write_owner" text COLLATE commerce_ai_ci DEFAULT 'COMMERCE' NOT NULL CHECK ("write_owner" IN ('COMMERCE','FULFILLMENT')),
    PRIMARY KEY ("singleton_id"),
    CONSTRAINT "chk_fulfillment_source_owner_frozen" CHECK (("write_owner" = 'COMMERCE') or ("frozen" = true)),
    CONSTRAINT "fulfillment_write_admission_chk_1" CHECK ("singleton_id" = 1)
);

COMMENT ON COLUMN "fulfillment_write_admission"."write_owner" IS '履约流程写入所有者，切换与回退均要求冻结商城新受理';

CREATE TABLE "inventory_catalog_event_inbox" (
    "event_id" varchar(100) COLLATE commerce_ai_ci NOT NULL,
    "product_id" bigint NOT NULL,
    "business_version" bigint NOT NULL,
    "payload_fingerprint" char(64) COLLATE commerce_ai_ci NOT NULL,
    "status" varchar(20) COLLATE commerce_ai_ci DEFAULT 'PROCESSING' NOT NULL,
    "created_at" timestamp(6) with time zone DEFAULT CURRENT_TIMESTAMP(6) NOT NULL,
    "processed_at" timestamp(6) with time zone,
    PRIMARY KEY ("event_id"),
    CONSTRAINT "chk_inventory_catalog_event_status" CHECK ("status" in ('PROCESSING','APPLIED','STALE'))
);

CREATE INDEX "idx_inventory_catalog_product" ON "inventory_catalog_event_inbox" ("product_id", "business_version");

CREATE TABLE "inventory_command_delivery_outbox" (
    "command_id" varchar(100) COLLATE commerce_ai_ci NOT NULL,
    "command_type" varchar(24) COLLATE commerce_ai_ci NOT NULL,
    "producer" varchar(50) COLLATE commerce_ai_ci NOT NULL,
    "order_id" bigint NOT NULL,
    "payload_fingerprint" char(64) COLLATE commerce_ai_ci NOT NULL,
    "payload" jsonb NOT NULL,
    "status" varchar(30) COLLATE commerce_ai_ci DEFAULT 'NEW' NOT NULL,
    "attempts" integer DEFAULT '0' NOT NULL,
    "next_attempt_at" timestamp(6) with time zone DEFAULT CURRENT_TIMESTAMP(6) NOT NULL,
    "result_deadline_at" timestamp(6) with time zone,
    "last_error" varchar(500) COLLATE commerce_ai_ci,
    "recovered_by" varchar(100) COLLATE commerce_ai_ci,
    "recovery_reason" varchar(300) COLLATE commerce_ai_ci,
    "recovered_at" timestamp(6) with time zone,
    "created_at" timestamp(6) with time zone DEFAULT CURRENT_TIMESTAMP(6) NOT NULL,
    "acknowledged_at" timestamp(6) with time zone,
    PRIMARY KEY ("command_id"),
    CONSTRAINT "chk_inventory_delivery_status" CHECK ("status" in ('NEW','IN_FLIGHT','RETRY','ACKNOWLEDGED','RECONCILIATION_REQUIRED','CLOSED')),
    CONSTRAINT "chk_inventory_delivery_type" CHECK ("command_type" in ('RESERVE','COMMIT','RELEASE','REFUND'))
);

CREATE INDEX "idx_inventory_delivery_dispatch" ON "inventory_command_delivery_outbox" ("status", "next_attempt_at");

CREATE TABLE "inventory_command_inbox" (
    "command_id" varchar(100) COLLATE commerce_ai_ci NOT NULL,
    "command_type" varchar(24) COLLATE commerce_ai_ci NOT NULL,
    "order_id" bigint NOT NULL,
    "payload_fingerprint" char(64) COLLATE commerce_ai_ci NOT NULL,
    "status" varchar(20) COLLATE commerce_ai_ci DEFAULT 'PROCESSING' NOT NULL,
    "created_at" timestamp(6) with time zone DEFAULT CURRENT_TIMESTAMP(6) NOT NULL,
    "processed_at" timestamp(6) with time zone,
    PRIMARY KEY ("command_id"),
    CONSTRAINT "chk_inventory_command_status" CHECK ("status" in ('PROCESSING','SUCCEEDED')),
    CONSTRAINT "chk_inventory_command_type" CHECK ("command_type" in ('RESERVE','COMMIT','RELEASE','REFUND'))
);

CREATE INDEX "idx_inventory_command_order" ON "inventory_command_inbox" ("order_id", "created_at");

CREATE TABLE "inventory_command_result_inbox" (
    "result_id" varchar(100) COLLATE commerce_ai_ci NOT NULL,
    "command_id" varchar(100) COLLATE commerce_ai_ci NOT NULL,
    "command_type" varchar(24) COLLATE commerce_ai_ci NOT NULL,
    "outcome" varchar(20) COLLATE commerce_ai_ci NOT NULL,
    "occurred_at" timestamp(6) with time zone NOT NULL,
    "error_code" varchar(80) COLLATE commerce_ai_ci,
    "message" varchar(500) COLLATE commerce_ai_ci NOT NULL,
    "correlation_id" varchar(100) COLLATE commerce_ai_ci NOT NULL,
    "causation_id" varchar(100) COLLATE commerce_ai_ci NOT NULL,
    "traceparent" varchar(55) COLLATE commerce_ai_ci NOT NULL,
    "received_at" timestamp(6) with time zone DEFAULT CURRENT_TIMESTAMP(6) NOT NULL,
    PRIMARY KEY ("result_id"),
    CONSTRAINT "chk_inventory_result_outcome" CHECK ("outcome" in ('SUCCEEDED','REJECTED')),
    CONSTRAINT "chk_inventory_result_type" CHECK ("command_type" in ('RESERVE','COMMIT','RELEASE','REFUND'))
);

ALTER TABLE "inventory_command_result_inbox" ADD CONSTRAINT "uk_inventory_result_command" UNIQUE ("command_id");

CREATE TABLE "inventory_movements" (
    "id" bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "event_id" varchar(100) COLLATE commerce_ai_ci NOT NULL,
    "order_id" bigint,
    "product_id" bigint NOT NULL,
    "movement_type" varchar(32) COLLATE commerce_ai_ci NOT NULL,
    "quantity" integer NOT NULL,
    "available_after" integer NOT NULL,
    "reserved_after" integer NOT NULL,
    "sold_after" integer NOT NULL,
    "detail" varchar(300) COLLATE commerce_ai_ci NOT NULL,
    "created_at" timestamp(6) with time zone DEFAULT CURRENT_TIMESTAMP(6) NOT NULL,
    PRIMARY KEY ("id")
);

CREATE INDEX "fk_inventory_movement_inventory" ON "inventory_movements" ("product_id");

CREATE INDEX "fk_inventory_movement_order" ON "inventory_movements" ("order_id");

ALTER TABLE "inventory_movements" ADD CONSTRAINT "uk_inventory_movement_event" UNIQUE ("event_id");

CREATE TABLE "inventory_reservations" (
    "id" bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "order_id" bigint NOT NULL,
    "product_id" bigint NOT NULL,
    "quantity" integer NOT NULL,
    "status" varchar(24) COLLATE commerce_ai_ci NOT NULL,
    "version" integer DEFAULT '0' NOT NULL,
    "reserved_at" timestamp(6) with time zone DEFAULT CURRENT_TIMESTAMP(6) NOT NULL,
    "committed_at" timestamp(6) with time zone,
    "released_at" timestamp(6) with time zone,
    PRIMARY KEY ("id"),
    CONSTRAINT "chk_inventory_reservation_quantity" CHECK ("quantity" > 0)
);

CREATE INDEX "fk_inventory_reservation_inventory" ON "inventory_reservations" ("product_id");

ALTER TABLE "inventory_reservations" ADD CONSTRAINT "uk_inventory_reservation_order_product" UNIQUE ("order_id", "product_id");

COMMENT ON TABLE "inventory_reservations" IS '订单结算建立的库存预占与转正或释放事实';

COMMENT ON COLUMN "inventory_reservations"."order_id" IS '触发库存预占的订单主键';

COMMENT ON COLUMN "inventory_reservations"."product_id" IS '被预占的商品主键';

COMMENT ON COLUMN "inventory_reservations"."quantity" IS '预占商品数量';

COMMENT ON COLUMN "inventory_reservations"."status" IS '预占状态：RESERVED、COMMITTED 或 RELEASED';

COMMENT ON COLUMN "inventory_reservations"."version" IS '乐观锁版本号';

CREATE TABLE "inventory_stocktake_reviews" (
    "reference" varchar(80) COLLATE commerce_ai_ci NOT NULL,
    "proposal" jsonb NOT NULL,
    "counted_by" varchar(100) COLLATE commerce_ai_ci NOT NULL,
    "approved_by" varchar(100) COLLATE commerce_ai_ci,
    "approved_at" timestamp(6) with time zone,
    "completed_at" timestamp(6) with time zone,
    "receipt" jsonb,
    "created_at" timestamp(6) with time zone DEFAULT CURRENT_TIMESTAMP(6) NOT NULL,
    "approval_reason" varchar(300) COLLATE commerce_ai_ci,
    PRIMARY KEY ("reference")
);

COMMENT ON COLUMN "inventory_stocktake_reviews"."approval_reason" IS '独立审批人的复核依据和处置理由';

CREATE TABLE "invoice_applications" (
    "order_id" bigint NOT NULL,
    "application_no" varchar(64) COLLATE commerce_ai_ci NOT NULL,
    "customer_id" bigint NOT NULL,
    "status" varchar(24) COLLATE commerce_ai_ci NOT NULL,
    "review_reason" varchar(80) COLLATE commerce_ai_ci,
    "review_detail" varchar(1024) COLLATE commerce_ai_ci,
    "next_check_at" timestamp(6) without time zone,
    "order_number" varchar(64) COLLATE commerce_ai_ci,
    "retry_after_id" bigint DEFAULT '0' NOT NULL,
    PRIMARY KEY ("order_id")
);

ALTER TABLE "invoice_applications" ADD CONSTRAINT "application_no" UNIQUE ("application_no");

CREATE INDEX "idx_invoice_customer" ON "invoice_applications" ("customer_id", "order_id");

CREATE INDEX "idx_invoice_due" ON "invoice_applications" ("next_check_at", "order_id");

CREATE INDEX "idx_invoice_order_number" ON "invoice_applications" ("order_number");

COMMENT ON COLUMN "invoice_applications"."order_id" IS '订单服务的订单主键';

COMMENT ON COLUMN "invoice_applications"."application_no" IS '同一订单的固定开票申请号';

COMMENT ON COLUMN "invoice_applications"."customer_id" IS '申请人和订单所有者';

COMMENT ON COLUMN "invoice_applications"."status" IS 'PENDING, ISSUED, EXHAUSTED, REVIEW_REQUIRED';

COMMENT ON COLUMN "invoice_applications"."review_reason" IS '需人工核对的错误码';

COMMENT ON COLUMN "invoice_applications"."review_detail" IS '金额、币种及关系差异的核对依据';

COMMENT ON COLUMN "invoice_applications"."next_check_at" IS 'UTC，NULL 表示已停止自动处理';

COMMENT ON COLUMN "invoice_applications"."order_number" IS '申请时读取的订单展示号，存量申请可为空';

COMMENT ON COLUMN "invoice_applications"."retry_after_id" IS '平台授权重试前最后一次已记录的尝试主键';

CREATE TABLE "invoice_attempts" (
    "id" bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "order_id" bigint NOT NULL,
    "request_id" varchar(64) COLLATE commerce_ai_ci NOT NULL,
    "kind" varchar(8) COLLATE commerce_ai_ci NOT NULL,
    "reference_no" varchar(64) COLLATE commerce_ai_ci NOT NULL,
    "payment_no" varchar(64) COLLATE commerce_ai_ci NOT NULL,
    "original_invoice_no" varchar(64) COLLATE commerce_ai_ci,
    "amount" decimal(18,2) NOT NULL,
    "currency" char(3) COLLATE commerce_ai_ci NOT NULL,
    "merchant_id" bigint,
    "gross_amount" decimal(18,2),
    "discount_amount" decimal(18,2),
    "freight_amount" decimal(18,2),
    "paid_amount" decimal(18,2),
    "status" varchar(12) COLLATE commerce_ai_ci NOT NULL,
    "invoice_no" varchar(64) COLLATE commerce_ai_ci,
    "failure_code" varchar(80) COLLATE commerce_ai_ci,
    "frozen_at" timestamp(6) without time zone DEFAULT CURRENT_TIMESTAMP(6) NOT NULL,
    PRIMARY KEY ("id"),
    CONSTRAINT "invoice_attempts_chk_1" CHECK ("amount" > 0)
);

CREATE INDEX "idx_invoice_attempt_order" ON "invoice_attempts" ("order_id", "kind", "id");

ALTER TABLE "invoice_attempts" ADD CONSTRAINT "invoice_no" UNIQUE ("invoice_no");

ALTER TABLE "invoice_attempts" ADD CONSTRAINT "request_id" UNIQUE ("request_id");

COMMENT ON COLUMN "invoice_attempts"."request_id" IS '持久化后传给发票平台的签名请求号';

COMMENT ON COLUMN "invoice_attempts"."kind" IS 'ISSUE 正票或 RED 红票';

COMMENT ON COLUMN "invoice_attempts"."reference_no" IS '开票申请号或成功退款单号';

COMMENT ON COLUMN "invoice_attempts"."payment_no" IS '正式支付账本的原支付单号';

COMMENT ON COLUMN "invoice_attempts"."original_invoice_no" IS '红票关联的正票号';

COMMENT ON COLUMN "invoice_attempts"."amount" IS '发送到发票平台的冻结金额';

COMMENT ON COLUMN "invoice_attempts"."merchant_id" IS '正票冻结时的单商家归属';

COMMENT ON COLUMN "invoice_attempts"."gross_amount" IS '正票冻结时订单行原价总额';

