    PRIMARY KEY ("order_id")
);

COMMENT ON COLUMN "line_after_sale_order_locks"."order_id" IS '串行化同一订单的退款和换货申请';

CREATE TABLE "line_after_sales" (
    "id" char(36) COLLATE commerce_ai_ci NOT NULL,
    "order_id" bigint NOT NULL,
    "order_line_id" bigint NOT NULL,
    "product_id" bigint NOT NULL,
    "customer_id" bigint NOT NULL,
    "merchant_id" bigint NOT NULL,
    "quantity" integer NOT NULL,
    "merchandise_amount" decimal(12,2) NOT NULL,
    "shipping_amount" decimal(12,2) NOT NULL,
    "currency" char(3) COLLATE commerce_ai_ci NOT NULL,
    "kind" varchar(24) COLLATE commerce_ai_ci NOT NULL,
    "status" varchar(24) COLLATE commerce_ai_ci NOT NULL,
    "reason" varchar(300) COLLATE commerce_ai_ci NOT NULL,
    "decision" varchar(300) COLLATE commerce_ai_ci,
    "tracking_number" varchar(120) COLLATE commerce_ai_ci,
    "refund_number" varchar(40) COLLATE commerce_ai_ci,
    "return_shipping_cost" decimal(12,2),
    "received_quantity" integer,
    "last_error" varchar(300) COLLATE commerce_ai_ci,
    "next_attempt_at" timestamp(6) with time zone DEFAULT CURRENT_TIMESTAMP(6) NOT NULL,
    "created_at" timestamp(6) with time zone DEFAULT CURRENT_TIMESTAMP(6) NOT NULL,
    "updated_at" timestamp(6) with time zone DEFAULT CURRENT_TIMESTAMP(6) NOT NULL,
    "active_order_id" bigint GENERATED ALWAYS AS ((case when ("status" not in ('COMPLETED','REJECTED','FAILED')) then "order_id" end)) STORED,
    "warehouse_id" bigint,
    "outbound_id" char(36) COLLATE commerce_ai_ci,
    "warehouse_return_status" varchar(24) COLLATE commerce_ai_ci,
    "approved_quantity" integer,
    "approved_merchandise_amount" decimal(12,2),
    PRIMARY KEY ("id"),
    CONSTRAINT "ck_line_after_sale_resolution" CHECK ((("approved_quantity" is null) and ("approved_merchandise_amount" is null)) or (("kind" = 'RETURN') and ("approved_quantity" is not null) and ("approved_quantity" between 1 and "quantity") and ("approved_merchandise_amount" is not null) and ("approved_merchandise_amount" >= 0) and ("approved_merchandise_amount" <= "merchandise_amount") and ("shipping_amount" = 0))),
    CONSTRAINT "ck_line_after_sales_amounts" CHECK (("quantity" > 0) and ("merchandise_amount" >= 0) and ("shipping_amount" >= 0))
);

CREATE INDEX "idx_line_after_sales_customer" ON "line_after_sales" ("customer_id", "order_id");

CREATE INDEX "idx_line_after_sales_merchant" ON "line_after_sales" ("merchant_id", "order_id");

CREATE INDEX "idx_line_after_sales_order" ON "line_after_sales" ("order_id");

CREATE INDEX "idx_line_after_sales_work" ON "line_after_sales" ("status", "next_attempt_at");

ALTER TABLE "line_after_sales" ADD CONSTRAINT "uk_line_after_sales_active_order" UNIQUE ("active_order_id");

COMMENT ON COLUMN "line_after_sales"."id" IS '稳定的售后单及跨服务操作标识';

COMMENT ON COLUMN "line_after_sales"."order_id" IS '订单服务中的原订单标识';

COMMENT ON COLUMN "line_after_sales"."order_line_id" IS '订单服务中冻结的订单行标识';

COMMENT ON COLUMN "line_after_sales"."product_id" IS '成交商品标识';

COMMENT ON COLUMN "line_after_sales"."customer_id" IS '原订单顾客';

COMMENT ON COLUMN "line_after_sales"."merchant_id" IS '下单快照中的商家';

COMMENT ON COLUMN "line_after_sales"."quantity" IS '本次申请的商品件数';

COMMENT ON COLUMN "line_after_sales"."merchandise_amount" IS '本次商品可退金额，含成交优惠分摊';

COMMENT ON COLUMN "line_after_sales"."shipping_amount" IS '本次原发货运费可退金额';

COMMENT ON COLUMN "line_after_sales"."currency" IS '订单成交币种';

COMMENT ON COLUMN "line_after_sales"."kind" IS 'BEFORE_SHIPMENT 或 RETURN';

COMMENT ON COLUMN "line_after_sales"."status" IS '售后处理阶段，包括待审核、待退货、执行中和终态';

COMMENT ON COLUMN "line_after_sales"."reason" IS '顾客的售后原因';

COMMENT ON COLUMN "line_after_sales"."decision" IS '商家审核或验收说明';

COMMENT ON COLUMN "line_after_sales"."tracking_number" IS '顾客填写的退回运单号';

COMMENT ON COLUMN "line_after_sales"."refund_number" IS '支付编排生成的退款编号';

COMMENT ON COLUMN "line_after_sales"."return_shipping_cost" IS '顾客登记的退回运费，不计入退款';

COMMENT ON COLUMN "line_after_sales"."received_quantity" IS '已确认的 WMS 实收件数，历史单保留原验收记录';

COMMENT ON COLUMN "line_after_sales"."last_error" IS '最近一次未完成操作的原因';

COMMENT ON COLUMN "line_after_sales"."warehouse_id" IS '按仓售后关联的原仓';

COMMENT ON COLUMN "line_after_sales"."outbound_id" IS '退货所对应的包裹和库存出库单';

CREATE TABLE "logistics_fulfillment_commands" (
    "command_id" char(36) COLLATE commerce_ai_ci NOT NULL,
    "operation" varchar(16) COLLATE commerce_ai_ci NOT NULL,
    "order_id" bigint NOT NULL,
    "order_number" varchar(64) COLLATE commerce_ai_ci,
    "carrier" varchar(100) COLLATE commerce_ai_ci NOT NULL,
