COMMENT ON COLUMN "logistics_fulfillment_commands"."order_id" IS '外部订单标识';

COMMENT ON COLUMN "logistics_fulfillment_commands"."order_number" IS '初始建单使用的原订单号';

COMMENT ON COLUMN "logistics_fulfillment_commands"."carrier" IS '受理时的承运商';

COMMENT ON COLUMN "logistics_fulfillment_commands"."tracking_number" IS '受理时的运单号';

COMMENT ON COLUMN "logistics_fulfillment_commands"."expected_version" IS '修改运单的前置版本';

COMMENT ON COLUMN "logistics_fulfillment_commands"."platform_shipment_no" IS '成功时记录的原渠道运单标识';

