CREATE TABLE "merchant_payout_attempts" (
    "id" char(36) COLLATE commerce_ai_ci NOT NULL,
    "statement_id" char(36) COLLATE commerce_ai_ci NOT NULL,
    "merchant_id" bigint NOT NULL,
    "amount" decimal(16,2) NOT NULL,
    "currency" char(3) COLLATE commerce_ai_ci NOT NULL,
    "status" varchar(16) COLLATE commerce_ai_ci NOT NULL,
    "simulate_failure" boolean NOT NULL,
    "requested_by" bigint NOT NULL,
    "channel_payout_no" varchar(50) COLLATE commerce_ai_ci,
    "created_at" timestamp(6) with time zone DEFAULT CURRENT_TIMESTAMP(6) NOT NULL,
    "resolved_at" timestamp(6) with time zone,
    "next_attempt_at" timestamp(6) with time zone DEFAULT CURRENT_TIMESTAMP(6) NOT NULL,
    "active_statement_id" char(36) COLLATE commerce_ai_ci GENERATED ALWAYS AS ((case when ("status" in ('REQUESTED','PENDING','SUCCEEDED')) then "statement_id" end)) STORED,
    "recovery_of" char(36) COLLATE commerce_ai_ci,
    "recovery_reason" varchar(300) COLLATE commerce_ai_ci,
    PRIMARY KEY ("id"),
    CONSTRAINT "ck_payout_amount" CHECK (("amount" > 0) and ("currency" = 'CNY')),
    CONSTRAINT "ck_payout_status" CHECK ("status" in ('REQUESTED','PENDING','SUCCEEDED','FAILED'))
);

ALTER TABLE "merchant_payout_attempts" ADD CONSTRAINT "channel_payout_no" UNIQUE ("channel_payout_no");

CREATE INDEX "ix_payout_dispatch" ON "merchant_payout_attempts" ("status", "next_attempt_at");

CREATE INDEX "ix_payout_statement" ON "merchant_payout_attempts" ("statement_id", "created_at");

ALTER TABLE "merchant_payout_attempts" ADD CONSTRAINT "uk_payout_active_statement" UNIQUE ("active_statement_id");

ALTER TABLE "merchant_payout_attempts" ADD CONSTRAINT "uk_payout_recovery_source" UNIQUE ("recovery_of");

COMMENT ON COLUMN "merchant_payout_attempts"."id" IS 'Stable signed channel attempt id';

COMMENT ON COLUMN "merchant_payout_attempts"."merchant_id" IS 'Merchant approved for the statement';

COMMENT ON COLUMN "merchant_payout_attempts"."status" IS 'REQUESTED, PENDING, SUCCEEDED or FAILED';

COMMENT ON COLUMN "merchant_payout_attempts"."recovery_of" IS '本次恢复对应的原失败打款尝试';

COMMENT ON COLUMN "merchant_payout_attempts"."recovery_reason" IS '管理员核对原渠道回执后的恢复理由';

