COMMENT ON COLUMN "merchant_settlement_statements"."id" IS 'The freeze request UUID and statement reference';

CREATE TABLE "merchant_shipping_rates" (
    "merchant_id" bigint NOT NULL,
    "country_code" varchar(2) COLLATE commerce_ai_ci NOT NULL,
    "state_province" varchar(100) COLLATE commerce_ai_ci NOT NULL,
    "fee" decimal(12,2) NOT NULL,
    "enabled" boolean DEFAULT true NOT NULL,
    PRIMARY KEY ("merchant_id", "country_code", "state_province"),
    CONSTRAINT "ck_merchant_shipping_rate" CHECK (("fee" >= 0) and ((("country_code" = '') and ("state_province" = '')) or ((char_length("country_code") = 2) and ("state_province" <> ''))))
);

COMMENT ON COLUMN "merchant_shipping_rates"."merchant_id" IS '拥有该规则的商城商家';

