COMMENT ON COLUMN "merchant_shipping_rates"."fee" IS '每单运费，人民币元';

COMMENT ON COLUMN "merchant_shipping_rates"."enabled" IS '区域运费是否参与结算匹配';

CREATE TABLE "merchant_statement_difference_dispositions" (
    "review_id" char(36) COLLATE commerce_ai_ci NOT NULL,
    "receipt_request_id" char(36) COLLATE commerce_ai_ci,
    "receipt" varchar(128) COLLATE commerce_ai_ci,
    "linked_by" bigint,
    "linked_at" timestamp(6) with time zone,
    "closure_request_id" char(36) COLLATE commerce_ai_ci,
    "closed_by" bigint,
