COMMENT ON COLUMN "merchant_statement_difference_dispositions"."closure_request_id" IS 'Idempotency key for closing the review';

COMMENT ON COLUMN "merchant_statement_difference_dispositions"."closed_by" IS 'Administrator who reran reconciliation and closed the review';

COMMENT ON COLUMN "merchant_statement_difference_dispositions"."closure_reason" IS 'Rationale for closing after reconciliation';

CREATE TABLE "merchant_statement_difference_reviews" (
    "request_id" char(36) COLLATE commerce_ai_ci NOT NULL,
    "statement_id" char(36) COLLATE commerce_ai_ci NOT NULL,
    "merchant_id" bigint NOT NULL,
    "order_id" bigint,
    "order_line_id" bigint,
    "difference_kind" varchar(64) COLLATE commerce_ai_ci NOT NULL,
    "evidence_reference" varchar(128) COLLATE commerce_ai_ci NOT NULL,
    "expected_value" decimal(24,2),
    "observed_value" decimal(24,2),
    "decision" varchar(16) COLLATE commerce_ai_ci NOT NULL,
    "reason" varchar(300) COLLATE commerce_ai_ci NOT NULL,
    "reviewed_by" bigint NOT NULL,
    "reviewed_at" timestamp(6) with time zone DEFAULT CURRENT_TIMESTAMP(6) NOT NULL,
    PRIMARY KEY ("request_id"),
    CONSTRAINT "chk_statement_difference_decision" CHECK ("decision" in ('CONFIRMED','NO_ACTION'))
);

CREATE INDEX "fk_statement_difference_review" ON "merchant_statement_difference_reviews" ("statement_id");

CREATE INDEX "idx_statement_difference_review_history" ON "merchant_statement_difference_reviews" ("merchant_id", "statement_id", "reviewed_at", "request_id");

COMMENT ON COLUMN "merchant_statement_difference_reviews"."request_id" IS '复核请求号，同一请求重试复用原记录';

COMMENT ON COLUMN "merchant_statement_difference_reviews"."statement_id" IS '被复核的冻结账单';

COMMENT ON COLUMN "merchant_statement_difference_reviews"."merchant_id" IS '冻结账单所属店铺';

COMMENT ON COLUMN "merchant_statement_difference_reviews"."order_id" IS '订单级差异所属订单';

COMMENT ON COLUMN "merchant_statement_difference_reviews"."order_line_id" IS '库存或仓库数量差异所属订单行';

COMMENT ON COLUMN "merchant_statement_difference_reviews"."difference_kind" IS '对账报告中的差异类型';

COMMENT ON COLUMN "merchant_statement_difference_reviews"."evidence_reference" IS '原账单、账本行或回执编号';

COMMENT ON COLUMN "merchant_statement_difference_reviews"."expected_value" IS '复核时报告的预期金额或件数';

COMMENT ON COLUMN "merchant_statement_difference_reviews"."observed_value" IS '复核时报告的实际金额或件数';

COMMENT ON COLUMN "merchant_statement_difference_reviews"."decision" IS 'CONFIRMED 确认差异，NO_ACTION 无需处置';

COMMENT ON COLUMN "merchant_statement_difference_reviews"."reason" IS '复核人填写的依据';

COMMENT ON COLUMN "merchant_statement_difference_reviews"."reviewed_by" IS '复核管理员账号';

COMMENT ON COLUMN "merchant_statement_difference_reviews"."reviewed_at" IS '登记复核的时间';

