CREATE TABLE "refund_records" (
    "id" bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "refund_number" varchar(40) COLLATE commerce_ai_ci NOT NULL,
    "order_id" bigint NOT NULL,
    "payment_id" bigint NOT NULL,
    "customer_id" bigint NOT NULL,
    "idempotency_key" varchar(80) COLLATE commerce_ai_ci NOT NULL,
    "request_fingerprint" varchar(64) COLLATE commerce_ai_ci NOT NULL,
    "amount" decimal(12,2) NOT NULL,
    "currency" varchar(3) COLLATE commerce_ai_ci NOT NULL,
    "reason_code" varchar(50) COLLATE commerce_ai_ci NOT NULL,
    "reason_detail" varchar(500) COLLATE commerce_ai_ci NOT NULL,
    "status" varchar(30) COLLATE commerce_ai_ci NOT NULL,
    "inventory_status" varchar(40) COLLATE commerce_ai_ci DEFAULT 'NOT_STARTED' NOT NULL,
    "order_status_before_refund" varchar(40) COLLATE commerce_ai_ci NOT NULL,
    "channel_refund_no" varchar(100) COLLATE commerce_ai_ci,
    "failure_reason" varchar(300) COLLATE commerce_ai_ci DEFAULT '' NOT NULL,
    "requested_at" timestamp(6) with time zone DEFAULT CURRENT_TIMESTAMP(6) NOT NULL,
    "succeeded_at" timestamp(6) with time zone,
    "failed_at" timestamp(6) with time zone,
    "created_at" timestamp(6) with time zone DEFAULT CURRENT_TIMESTAMP(6) NOT NULL,
    "updated_at" timestamp(6) with time zone DEFAULT CURRENT_TIMESTAMP(6) NOT NULL,
    "version" integer DEFAULT '0' NOT NULL,
    PRIMARY KEY ("id"),
    CONSTRAINT "chk_refund_amount" CHECK ("amount" > 0),
    CONSTRAINT "chk_refund_inventory_status" CHECK ("inventory_status" in ('NOT_STARTED','WAITING','REFUNDED','RECONCILIATION_REQUIRED'))
);

