ALTER TABLE "refund_records" ADD CONSTRAINT "uk_refund_number" UNIQUE ("refund_number");

ALTER TABLE "refund_records" ADD CONSTRAINT "uk_refund_payment" UNIQUE ("payment_id");

COMMENT ON TABLE "refund_records" IS '商城侧整单全额退款单及渠道退款投影';

COMMENT ON COLUMN "refund_records"."refund_number" IS '商城生成的退款单号';

COMMENT ON COLUMN "refund_records"."order_id" IS '退款所属订单内部主键';

COMMENT ON COLUMN "refund_records"."payment_id" IS '被退款的成功支付记录主键';

COMMENT ON COLUMN "refund_records"."customer_id" IS '申请退款的客户用户主键';

COMMENT ON COLUMN "refund_records"."idempotency_key" IS '退款请求幂等键';

COMMENT ON COLUMN "refund_records"."amount" IS '申请退回金额，币种见 currency';

COMMENT ON COLUMN "refund_records"."currency" IS 'ISO 4217 退款币种代码';

COMMENT ON COLUMN "refund_records"."status" IS '退款状态机当前状态';

COMMENT ON COLUMN "refund_records"."order_status_before_refund" IS '退款开始前的订单状态，失败时用于恢复';

COMMENT ON COLUMN "refund_records"."channel_refund_no" IS '支付渠道返回的退款号';

COMMENT ON COLUMN "refund_records"."succeeded_at" IS '渠道确认退款成功的时刻';

