CREATE TABLE "scheduled_task_policies" (
    "task_type" varchar(64) COLLATE commerce_ai_ci NOT NULL,
    "enabled" boolean NOT NULL,
    "primary_trigger" varchar(20) COLLATE commerce_ai_ci NOT NULL,
    "reconciliation_enabled" boolean NOT NULL,
    "grace_period_seconds" bigint NOT NULL,
    "claim_lease_seconds" bigint NOT NULL,
    "max_attempts" integer NOT NULL,
    "retry_delay_seconds" bigint NOT NULL,
    "config_version" bigint DEFAULT '1' NOT NULL,
    "updated_by" varchar(190) COLLATE commerce_ai_ci NOT NULL,
    "created_at" timestamp(6) with time zone DEFAULT CURRENT_TIMESTAMP(6) NOT NULL,
    "updated_at" timestamp(6) with time zone DEFAULT CURRENT_TIMESTAMP(6) NOT NULL,
    PRIMARY KEY ("task_type"),
    CONSTRAINT "chk_scheduled_policy_attempts" CHECK ("max_attempts" > 0),
    CONSTRAINT "chk_scheduled_policy_grace" CHECK ("grace_period_seconds" >= 0),
    CONSTRAINT "chk_scheduled_policy_lease" CHECK ("claim_lease_seconds" > 0),
    CONSTRAINT "chk_scheduled_policy_retry" CHECK ("retry_delay_seconds" >= 0),
    CONSTRAINT "chk_scheduled_policy_trigger" CHECK ("primary_trigger" in ('DATABASE','RABBITMQ','ROCKETMQ'))
);

CREATE TABLE "scheduled_task_policy_events" (
    "id" bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "task_type" varchar(64) COLLATE commerce_ai_ci NOT NULL,
    "action" varchar(24) COLLATE commerce_ai_ci NOT NULL,
    "enabled" boolean NOT NULL,
    "primary_trigger" varchar(20) COLLATE commerce_ai_ci NOT NULL,
    "reconciliation_enabled" boolean NOT NULL,
    "grace_period_seconds" bigint NOT NULL,
    "claim_lease_seconds" bigint NOT NULL,
    "max_attempts" integer NOT NULL,
    "retry_delay_seconds" bigint NOT NULL,
    "config_version" bigint NOT NULL,
    "operated_by" varchar(190) COLLATE commerce_ai_ci NOT NULL,
    "created_at" timestamp(6) with time zone DEFAULT CURRENT_TIMESTAMP(6) NOT NULL,
    PRIMARY KEY ("id")
);

CREATE INDEX "idx_scheduled_policy_event_type" ON "scheduled_task_policy_events" ("task_type", "created_at");

CREATE TABLE "scheduled_tasks" (
    "id" bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "task_key" varchar(128) COLLATE commerce_ai_ci NOT NULL,
    "task_type" varchar(64) COLLATE commerce_ai_ci NOT NULL,
    "aggregate_type" varchar(64) COLLATE commerce_ai_ci NOT NULL,
    "aggregate_id" varchar(128) COLLATE commerce_ai_ci NOT NULL,
    "payload_json" jsonb NOT NULL,
    "status" varchar(24) COLLATE commerce_ai_ci NOT NULL,
    "due_at" timestamp(6) with time zone NOT NULL,
    "primary_trigger_snapshot" varchar(20) COLLATE commerce_ai_ci NOT NULL,
    "reconciliation_enabled_snapshot" boolean NOT NULL,
    "grace_period_seconds_snapshot" bigint NOT NULL,
    "claim_lease_seconds_snapshot" bigint NOT NULL,
    "max_attempts" integer NOT NULL,
    "retry_delay_seconds_snapshot" bigint NOT NULL,
    "policy_version_snapshot" bigint NOT NULL,
    "attempts" integer DEFAULT '0' NOT NULL,
    "lease_until" timestamp(6) with time zone,
    "claimed_by" varchar(190) COLLATE commerce_ai_ci,
    "last_trigger_source" varchar(32) COLLATE commerce_ai_ci,
    "trigger_published_at" timestamp(6) with time zone,
    "trigger_publish_attempts" integer DEFAULT '0' NOT NULL,
    "trigger_last_error" varchar(1000) COLLATE commerce_ai_ci,
    "last_error" varchar(1000) COLLATE commerce_ai_ci,
    "completed_at" timestamp(6) with time zone,
    "cancelled_at" timestamp(6) with time zone,
    "version" integer DEFAULT '0' NOT NULL,
    "created_at" timestamp(6) with time zone DEFAULT CURRENT_TIMESTAMP(6) NOT NULL,
    "updated_at" timestamp(6) with time zone DEFAULT CURRENT_TIMESTAMP(6) NOT NULL,
    PRIMARY KEY ("id"),
    CONSTRAINT "chk_scheduled_task_status" CHECK ("status" in ('CREATED','SCHEDULED','PROCESSING','SUCCEEDED','FAILED','CANCELLED')),
    CONSTRAINT "chk_scheduled_task_trigger" CHECK ("primary_trigger_snapshot" in ('DATABASE','RABBITMQ','ROCKETMQ'))
);

CREATE INDEX "idx_scheduled_task_aggregate" ON "scheduled_tasks" ("aggregate_type", "aggregate_id");

CREATE INDEX "idx_scheduled_task_due" ON "scheduled_tasks" ("primary_trigger_snapshot", "status", "due_at");

CREATE INDEX "idx_scheduled_task_lease" ON "scheduled_tasks" ("status", "lease_until");

CREATE INDEX "idx_scheduled_task_reconcile" ON "scheduled_tasks" ("reconciliation_enabled_snapshot", "status", "due_at");

CREATE INDEX "idx_scheduled_tasks_trigger_publish" ON "scheduled_tasks" ("primary_trigger_snapshot", "status", "trigger_published_at", "due_at", "id");

ALTER TABLE "scheduled_tasks" ADD CONSTRAINT "uk_scheduled_task_key" UNIQUE ("task_type", "task_key");

COMMENT ON TABLE "scheduled_tasks" IS '通用业务定时任务，保存策略快照、租约与重试状态';

COMMENT ON COLUMN "scheduled_tasks"."task_key" IS '业务稳定幂等键';

COMMENT ON COLUMN "scheduled_tasks"."task_type" IS '任务类型，用于选择统一执行 Handler';

COMMENT ON COLUMN "scheduled_tasks"."aggregate_type" IS '关联业务聚合类型';

COMMENT ON COLUMN "scheduled_tasks"."aggregate_id" IS '关联业务聚合标识';

COMMENT ON COLUMN "scheduled_tasks"."payload_json" IS '执行 Handler 需要的业务快照';

COMMENT ON COLUMN "scheduled_tasks"."status" IS '任务状态机当前状态';

COMMENT ON COLUMN "scheduled_tasks"."due_at" IS '任务首次允许执行的时刻';

COMMENT ON COLUMN "scheduled_tasks"."primary_trigger_snapshot" IS '创建任务时固化的主触发策略';

COMMENT ON COLUMN "scheduled_tasks"."reconciliation_enabled_snapshot" IS '创建任务时固化的数据库对账开关';

COMMENT ON COLUMN "scheduled_tasks"."claim_lease_seconds_snapshot" IS '创建任务时固化的领取租约秒数';

COMMENT ON COLUMN "scheduled_tasks"."max_attempts" IS '任务允许的最大执行次数';

COMMENT ON COLUMN "scheduled_tasks"."retry_delay_seconds_snapshot" IS '创建任务时固化的重试间隔秒数';

COMMENT ON COLUMN "scheduled_tasks"."lease_until" IS '当前执行者的租约到期时刻';

COMMENT ON COLUMN "scheduled_tasks"."claimed_by" IS '当前领取任务的实例标识';

COMMENT ON COLUMN "scheduled_tasks"."last_trigger_source" IS '最近一次尝试执行的实际触发来源';

COMMENT ON COLUMN "scheduled_tasks"."completed_at" IS '任务执行成功的时刻';

COMMENT ON COLUMN "scheduled_tasks"."cancelled_at" IS '任务被业务流程取消的时刻';

