CREATE TABLE "shipment_records" (
    "id" bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "order_id" bigint NOT NULL,
    "merchant_shipment_no" varchar(100) COLLATE commerce_ai_ci NOT NULL,
    "platform_shipment_no" varchar(100) COLLATE commerce_ai_ci,
    "carrier" varchar(100) COLLATE commerce_ai_ci NOT NULL,
    "tracking_number" varchar(120) COLLATE commerce_ai_ci NOT NULL,
    "status" varchar(40) COLLATE commerce_ai_ci NOT NULL,
    "shipped_at" timestamp(6) with time zone,
    "delivered_at" timestamp(6) with time zone,
    "last_reconciled_at" timestamp(6) with time zone,
    "reconciliation_error" varchar(1000) COLLATE commerce_ai_ci,
    "created_at" timestamp(6) with time zone DEFAULT CURRENT_TIMESTAMP(6) NOT NULL,
    "updated_at" timestamp(6) with time zone DEFAULT CURRENT_TIMESTAMP(6) NOT NULL,
    "shipment_version" bigint DEFAULT '0' NOT NULL,
    "after_sale_id" char(36) COLLATE commerce_ai_ci,
    "order_number" varchar(100) COLLATE commerce_ai_ci,
    "last_event_at" timestamp(6) with time zone,
    "return_carrier" varchar(100) COLLATE commerce_ai_ci GENERATED ALWAYS AS ((case when ("after_sale_id" is not null) then "carrier" end)) STORED,
    "package_id" char(36) COLLATE commerce_ai_ci,
    "package_delivery_checked_at" timestamp(6) with time zone,
    "package_delivery_reported" boolean DEFAULT false NOT NULL,
    "outbound_order_id" bigint GENERATED ALWAYS AS ((case when (("after_sale_id" is null) and ("package_id" is null)) then "order_id" end)) STORED,
    "replacement" boolean DEFAULT false NOT NULL,
