COMMENT ON TABLE "shipment_records" IS '商城侧物流运单投影及对账状态';

COMMENT ON COLUMN "shipment_records"."order_id" IS '运单所属商城订单内部主键';

COMMENT ON COLUMN "shipment_records"."merchant_shipment_no" IS '商城生成并发送给物流平台的运单号';

COMMENT ON COLUMN "shipment_records"."platform_shipment_no" IS '物流平台返回的运单号';

COMMENT ON COLUMN "shipment_records"."tracking_number" IS '承运商查件单号';

COMMENT ON COLUMN "shipment_records"."status" IS '商城投影的物流状态';

COMMENT ON COLUMN "shipment_records"."delivered_at" IS '物流平台确认送达的时刻';

COMMENT ON COLUMN "shipment_records"."last_reconciled_at" IS '最近一次主动对账成功时刻';

COMMENT ON COLUMN "shipment_records"."shipment_version" IS '商城物流投影的运单详情版本';

COMMENT ON COLUMN "shipment_records"."after_sale_id" IS 'Return case reference. NULL identifies an outbound shipment.';

COMMENT ON COLUMN "shipment_records"."order_number" IS 'Order number for replaying a return registration.';

COMMENT ON COLUMN "shipment_records"."last_event_at" IS 'Carrier time of the latest applied return tracking event.';

COMMENT ON COLUMN "shipment_records"."package_id" IS '多包裹正向发货标识';

COMMENT ON COLUMN "shipment_records"."package_delivery_checked_at" IS '最近一次核对整单送达的时间';

COMMENT ON COLUMN "shipment_records"."package_delivery_reported" IS '该单已向订单服务报告所有包裹送达';

COMMENT ON COLUMN "shipment_records"."replacement" IS '售后关联运单是否用于补发换货件';

CREATE TABLE "shipping_addresses" (
    "id" bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "user_id" bigint NOT NULL,
    "recipient_name" varchar(100) COLLATE commerce_ai_ci NOT NULL,
    "phone" varchar(40) COLLATE commerce_ai_ci NOT NULL,
    "country_code" varchar(2) COLLATE commerce_ai_ci NOT NULL,
    "state_province" varchar(100) COLLATE commerce_ai_ci NOT NULL,
    "city" varchar(100) COLLATE commerce_ai_ci NOT NULL,
    "district" varchar(100) COLLATE commerce_ai_ci NOT NULL,
    "address_line1" varchar(300) COLLATE commerce_ai_ci NOT NULL,
    "address_line2" varchar(300) COLLATE commerce_ai_ci,
    "postal_code" varchar(20) COLLATE commerce_ai_ci NOT NULL,
    "label" varchar(40) COLLATE commerce_ai_ci NOT NULL,
    "is_default" boolean DEFAULT false NOT NULL,
    "created_at" timestamp(6) with time zone DEFAULT CURRENT_TIMESTAMP(6) NOT NULL,
    "updated_at" timestamp(6) with time zone DEFAULT CURRENT_TIMESTAMP(6) NOT NULL,
    PRIMARY KEY ("id")
);

CREATE INDEX "idx_shipping_addresses_user" ON "shipping_addresses" ("user_id");

